// Test slice reducer (pure function):
import tasksReducer, { addTask, toggleTask } from './tasksSlice';

describe('tasksSlice', () => {
  const initialState = { items: [], loading: false, error: null };

  it('should add a task', () => {
    const task = { id: '1', title: 'Test', completed: false };
    const state = tasksReducer(initialState, addTask(task));
    expect(state.items).toHaveLength(1);
    expect(state.items[0].title).toBe('Test');
  });

  it('should toggle a task', () => {
    const stateWithTask = { ...initialState, items: [{ id: '1', title: 'Test', completed: false }] };
    const state = tasksReducer(stateWithTask, toggleTask('1'));
    expect(state.items[0].completed).toBe(true);
  });
});

